from typing import List
import heapq


def findMedianSortedArrays(nums1: List[int], nums2: List[int]) -> float:
    """
    Find the median of two sorted arrays in O(log(min(m, n))) time by binary searching
    the partition point on the smaller array.
    """
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1

    m, n = len(nums1), len(nums2)
    total_left = (m + n + 1) // 2

    left, right = 0, m
    while left <= right:
        i = (left + right) // 2
        j = total_left - i

        nums1_left_max = float("-inf") if i == 0 else nums1[i - 1]
        nums1_right_min = float("inf") if i == m else nums1[i]
        nums2_left_max = float("-inf") if j == 0 else nums2[j - 1]
        nums2_right_min = float("inf") if j == n else nums2[j]

        if nums1_left_max <= nums2_right_min and nums2_left_max <= nums1_right_min:
            if (m + n) % 2 == 1:
                return float(max(nums1_left_max, nums2_left_max))
            return (max(nums1_left_max, nums2_left_max) + min(nums1_right_min, nums2_right_min)) / 2.0
        elif nums1_left_max > nums2_right_min:
            right = i - 1
        else:
            left = i + 1

    raise ValueError("Input arrays are not sorted or invalid.")


class StreamingMedian:
    """
    Maintains the median of a stream using two heaps (max-heap for lower half,
    min-heap for upper half).
    """

    def __init__(self) -> None:
        self._lower: List[int] = []  # max-heap (store as negatives)
        self._upper: List[int] = []  # min-heap

    def add(self, num: int) -> None:
        if not self._lower or num <= -self._lower[0]:
            heapq.heappush(self._lower, -num)
        else:
            heapq.heappush(self._upper, num)

        if len(self._lower) > len(self._upper) + 1:
            heapq.heappush(self._upper, -heapq.heappop(self._lower))
        elif len(self._upper) > len(self._lower) + 1:
            heapq.heappush(self._lower, -heapq.heappop(self._upper))

    def median(self) -> float:
        if not self._lower and not self._upper:
            raise ValueError("No elements have been added yet.")

        if len(self._lower) == len(self._upper):
            return (-self._lower[0] + self._upper[0]) / 2.0
        if len(self._lower) > len(self._upper):
            return float(-self._lower[0])
        return float(self._upper[0])
